INSERT INTO `blend_plan_feedback` (`id`, `plan_id`, `order_id`, `actual_quantity`, `actual_ash`, `actual_sulfur`, `actual_moisture`, `actual_volatile`, `actual_calorific`, `actual_cost`, `qualified_flag`, `effectiveness_eval`, `feedback_desc`, `execute_date`, `operator_id`, `case_generated_flag`, `case_id`, `status`, `create_time`, `update_time`)
VALUES
	(1,1,1,5000.00,10.68,0.65,6.88,32.40,6048.00,2535000.00,1,'优秀','方案执行稳定，最终产品质量余量充足，适合作为低硫高热值订单参考案例。','2026-04-26',1,1,1,1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(2,2,2,3200.00,13.18,0.61,7.25,33.10,5735.00,1712000.00,0,'一般','方案理论满足但硫分余量不足，最终硫分略超订单上限，建议提高低硫精煤比例。','2026-04-26',1,1,2,1,'2026-04-25 16:14:38','2026-04-25 16:14:38');
INSERT INTO `case_sample` (`id`, `case_code`, `case_name`, `order_desc`, `blend_desc`, `result_desc`, `quality_result`, `cost_result`, `effectiveness_eval`, `status`, `create_time`, `update_time`, `business_stage`, `related_batch_no`, `related_order_id`)
VALUES
	(1,'C2026042501','低硫高热值商品煤配煤成功案例','客户要求5000吨动力煤，灰分≤18%，硫分≤0.80%，发热量≥5000kcal/kg。','PB2026042501-CL 60% + PB2026042502-CL 40%，形成FP2026042501。','最终质检合格并完成发运，质量余量充足。','灰分10.68%，硫分0.652%，水分6.88%，发热量6048kcal/kg',2535000.00,'优秀',0,'2026-04-25 16:14:38','2026-05-29 09:10:01','feedback','FP2026042501',1),
	(2,'C2026042502','严格低硫订单风险反馈案例','客户要求3200吨动力煤，灰分≤16%，硫分≤0.60%，发热量≥5200kcal/kg。','PB2026042501-CL 37.5% + PB2026042502-CL 62.5%，理论满足但硫分余量不足。','最终质检硫分0.610%，略高于订单上限，需要调整低硫煤比例。','灰分13.18%，硫分0.610%，水分7.25%，发热量5735kcal/kg',1712000.00,'一般',0,'2026-04-25 16:14:38','2026-05-29 09:10:01','feedback','FP2026042502',2),
	(3,'C2026042503','成本优先动力煤候选案例','客户要求4500吨动力煤，灰分≤22%，硫分≤1.20%，发热量≥4700kcal/kg，成本优先。','PB2026042601-CL 70% + PB2026042501-CL 30%。','预测满足质量要求且成本较低，尚未执行。','预测灰分15.18%，硫分0.568%，水分8.93%，发热量5375kcal/kg',2012500.00,'良好',0,'2026-04-25 16:14:38','2026-05-29 09:10:01','blending',NULL,3),
	(4,'CS-TUNE-001','低硫电煤成功案例','5000吨低硫电煤，要求硫分≤0.60%、热值≥5500 kcal/kg。','神府低硫长焰煤50% + 鄂尔多斯低硫煤30% + 准东五彩湾高水分煤20%。','最终硫分0.47%，灰分9.8%，水分8.9%，热值5740 kcal/kg，满足订单约束。','合格：低硫余量充足，热值达标',2595000.00,'优秀',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(5,'CS-TUNE-002','成本优先电煤成功案例','8000吨经济煤，灰分≤22%、硫分≤1.20%、热值≥4800。','平朔高灰动力煤45% + 准东五彩湾高水分煤35% + 晋北中硫动力煤20%。','最终灰分18.6%，硫分0.71%，热值5050 kcal/kg，成本较低。','合格：成本优势明显',3480000.00,'良好',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(6,'CS-TUNE-003','高水分煤超配风险案例','3000吨环保电煤，水分≤9%、硫分≤0.60%。','准东五彩湾高水分煤50% + 神府低硫长焰煤50%。','最终水分9.7%，超过订单上限，虽硫分达标但水分不合格。','不合格：水分超限',1455000.00,'较差',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(7,'CS-TUNE-004','高热值应急订单成功案例','2500吨高热值订单，要求热值≥6200 kcal/kg。','榆林高热值不粘煤60% + 神府低硫长焰煤40%。','最终热值6460 kcal/kg，硫分0.40%，成本偏高但满足应急要求。','合格：热值余量充足',1515000.00,'良好',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(8,'CS-TUNE-005','中硫煤限配案例','5200吨中等质量订单，硫分≤0.85%、热值≥5300。','晋北中硫动力煤20% + 鄂尔多斯低硫煤40% + 神府低硫长焰煤40%。','最终硫分0.56%，热值5740 kcal/kg，质量稳定。','合格：中硫煤比例受控',2760000.00,'优秀',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(9,'CS-TUNE-006','褐煤低成本边界案例','10000吨低价保供订单，热值≥4300、水分≤18%。','蒙西低成本褐煤40% + 平朔高灰动力煤30% + 准东五彩湾高水分煤30%。','最终水分16.4%，热值4550 kcal/kg，满足低价保供要求。','合格：低成本但质量余量较小',3720000.00,'一般',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(10,'CS-TUNE-007','严格商品煤失败案例','3200吨严格商品煤，灰分≤10%、硫分≤0.55%、水分≤8%。','神府低硫长焰煤45% + 鄂尔多斯低硫煤35% + 准东五彩湾煤20%。','最终水分8.7%，超过上限；原因是高水分煤比例偏高。','不合格：水分边界控制不足',1760000.00,'较差',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(11,'CS-TUNE-008','气化用煤成功案例','3600吨煤化工气化用煤，挥发分参考34%、热值≥5600、硫分≤0.80%。','宁东气化用煤50% + 神府低硫长焰煤30% + 榆林高热值不粘煤20%。','最终挥发分33.9%，热值6020 kcal/kg，硫分0.48%，满足气化用煤要求。','合格：气化指标匹配较好',1980000.00,'优秀',0,'2026-04-25 22:05:30','2026-05-29 09:10:01','blending',NULL,NULL),
	(12,'CS-EXP-001','严格低硫高热值电煤成功案例','5000吨低硫高热值电煤，要求灰分≤14%、硫分≤0.60%、水分≤10%、发热量≥5600 kcal/kg。','神府低硫长焰煤实验批次45% + 鄂尔多斯低硫动力煤实验批次35% + 榆林高热值不粘煤实验批次20%。','预测硫分约0.41%，热值约6110 kcal/kg，质量余量较充足，成本中等偏高。','预测合格：硫分余量充足，热值达标',2792500.00,'优秀',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-SF-20260505-CL',NULL),
	(13,'CS-EXP-002','成本优先保供成功案例','9000吨经济电煤，灰分≤22%、硫分≤1.20%、水分≤16%、发热量≥4600 kcal/kg，成本优先。','准东五彩湾高水分低硫煤实验批次45% + 平朔高灰动力煤实验批次35% + 晋北中硫动力煤实验批次20%。','预测灰分约15.9%、硫分约0.68%、水分约13.2%、热值约4890 kcal/kg，成本较低但水分余量较小。','预测合格：成本优势明显，需关注水分余量',3712500.00,'良好',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-ZD-20260505-DL',NULL),
	(14,'CS-EXP-003','气化用煤指标匹配案例','3600吨煤化工气化用煤，要求灰分≤13%、硫分≤0.80%、水分≤9%、挥发分参考34%、热值≥5600 kcal/kg。','宁东气化用煤实验批次50% + 鄂尔多斯低硫动力煤实验批次30% + 神府低硫长焰煤实验批次20%。','预测挥发分约34.2%、热值约5895 kcal/kg、硫分约0.49%，满足气化用煤主要约束。','预测合格：挥发分和热值匹配较好',1933200.00,'优秀',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-ND-20260505-QH',NULL),
	(15,'CS-EXP-004','严格商品煤边界风险案例','3200吨严格商品煤，灰分≤10%、硫分≤0.55%、水分≤8%、热值≥6000 kcal/kg。','神府低硫长焰煤实验批次50% + 鄂尔多斯低硫动力煤实验批次30% + 榆林高热值不粘煤实验批次20%。','预测质量接近边界，若引入高水分煤会导致水分超限，应提示不可使用高水分低价煤。','边界合格：水分和灰分约束需重点关注',1774400.00,'良好',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-ERDS-20260505-DL',NULL),
	(16,'CS-EXP-005','库存消纳型配煤案例','7000吨库存消纳订单，灰分≤20%、硫分≤1.10%、水分≤13%、热值≥5000 kcal/kg。','晋北中硫动力煤实验批次40% + 准东五彩湾高水分低硫煤实验批次30% + 鄂尔多斯低硫动力煤实验批次30%。','预测质量达标并消纳中硫库存，但准东煤比例过高会带来水分风险。','预测合格：库存利用较好，水分余量一般',3395000.00,'良好',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-JB-20260505-DL',NULL),
	(17,'CS-EXP-006','高热值应急补仓案例','2500吨高热值应急订单，要求灰分≤15%、硫分≤0.90%、水分≤10%、热值≥6200 kcal/kg。','榆林高热值不粘煤实验批次60% + 神府低硫长焰煤实验批次40%。','预测热值约6340 kcal/kg，硫分约0.42%，成本偏高但满足应急交付要求。','预测合格：热值余量充足，成本偏高',1512500.00,'良好',0,'2026-05-08 09:12:26','2026-05-29 09:10:01','blending','PB-EXP-YL-20260505-CL',NULL),
	(18,'CS-EXP26-001','低硫高热电煤成功案例','5000吨低硫高热订单，硫分≤0.60%，热值≥5600 kcal/kg。','采用神木低灰煤、府谷低硫煤与鄂尔多斯均衡煤组合，控制高硫煤参与比例。','质量达标，热值余量充足，成本略高但符合优先级要求。','灰分、硫分和热值均满足要求',2520000.00,'质量优先订单可参考',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-SM-001',NULL),
	(19,'CS-EXP26-002','成本保供成功案例','9000吨成本敏感订单，灰分和硫分约束相对宽松。','采用五彩湾低成本煤、晋北中硫煤与少量鄂尔多斯均衡煤组合。','在满足硬约束前提下降低吨煤成本。','质量达标，成本较低',3303000.00,'成本优先订单可参考',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-WCW-001',NULL),
	(20,'CS-EXP26-003','库存消纳风险案例','7000吨库存消纳订单，要求热值≥5000 kcal/kg。','五彩湾低成本煤为主，搭配晋北或榆林煤进行热值补偿。','方案达标但热值余量较小，执行前需复核煤质。','热值边界，风险参考',2786000.00,'库存消纳订单需关注热值余量',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-WCW-001',NULL),
	(21,'CS-EXP26-004','边界商品煤复核案例','3200吨严格商品煤订单，灰分≤10%，硫分≤0.55%，热值≥6000。','使用神木、府谷、沁水优质煤组合，避免低价高灰煤参与。','质量满足但优质煤库存消耗较快。','边界质量达标，库存需关注',1760000.00,'严格订单需优先保证质量',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-QS-001',NULL),
	(22,'CS-EXP26-005','水分严格控制案例','4500吨水分≤7.5%的订单。','引入哈密低水分煤与神木低灰煤，限制高水分准东煤和煤泥。','水分达标，成本中等。','水分控制有效',2150000.00,'水分严格订单可参考',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-HM-001',NULL),
	(23,'CS-EXP26-006','高硫煤限配失败案例','低硫订单中错误加入过高比例高硫煤。','吕梁高硫煤比例过高导致硫分超限。','方案不可执行，应降低高硫煤比例或替换为低硫煤。','硫分超限',1900000.00,'作为反例用于RAG解释',1,'2026-05-29 09:10:01','2026-05-29 09:10:01','blending','PB-EXP26-LL-001',NULL);
