INSERT INTO `rag_chunk` (`id`, `document_id`, `chunk_code`, `chunk_text`, `chunk_index`, `token_count`, `tags`, `source_type`, `source_id`, `vector_id`, `embedding_model`, `status`, `create_time`, `update_time`)
VALUES
	(1,1,'RAG-EXP26-001-C001','低硫订单应优先选择硫分低于0.60%的煤种。若候选煤中存在高硫煤，应限制其比例，并通过低硫高热煤进行补偿。系统在硫分余量不足时应返回风险提示。',1,71,'低硫,硫分约束,高硫煤限配,质量控制','rag_knowledge',42,'1','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(2,2,'RAG-EXP26-002-C001','高热值订单通常需要使用神木、府谷、沁水、大同等高热值煤种。低热值低价煤可用于成本控制，但比例过高会导致热值安全余量不足。',1,60,'高热值,热值补偿,动力煤,风险提示','rag_knowledge',43,'2','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(3,3,'RAG-EXP26-003-C001','库存消纳订单的目标是在满足质量约束的前提下提高积压煤使用比例。若方案刚好达到热值下限或水分接近上限，应标记为风险参考，并建议执行前复核最新化验结果。',1,74,'库存消纳,低成本,热值边界,风险参考','rag_knowledge',44,'3','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(4,4,'RAG-EXP26-004-C001','当水分上限小于等于8.0%时，应优先选择低水分煤种，限制准东高水分煤和煤泥参与。水分余量不足可能造成交付验收风险。',1,57,'水分控制,低水分,准东煤,煤泥','rag_knowledge',45,'4','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(5,5,'RAG-EXP26-005-C001','低价煤种可以降低吨煤成本，但低价煤往往伴随灰分、水分较高或热值较低的问题。成本优先策略仍需保留质量评分和风险识别，避免低成本不可执行方案。',1,69,'成本控制,低价煤,灰分控制,热值不足','rag_knowledge',46,'5','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(6,6,'RAG-EXP26-006-C001','单煤依赖是指某一煤种在配煤方案中占比过高。该情况会放大单一煤源煤质波动对最终产品质量的影响，通常需要引入第二或第三种煤进行稳定性补偿。',1,67,'单煤依赖,稳定性,配比风险','rag_knowledge',47,'6','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(7,7,'RAG-EXP26-007-C001','历史案例显示，神木低灰低硫煤、府谷低硫煤与鄂尔多斯均衡煤组合适合低硫高热订单，但成本相对较高，适合高优先级客户。',1,56,'低硫高热,历史案例,质量优先','rag_knowledge',48,'7','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(8,8,'RAG-EXP26-008-C001','在灰分和硫分约束较宽松的保供订单中，五彩湾低成本煤、晋北中硫煤和少量均衡煤组合能够降低吨煤成本，同时保持基本质量达标。',1,59,'成本保供,历史案例,五彩湾,晋北','rag_knowledge',49,'8','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(9,9,'RAG-EXP26-009-C001','当方案预测灰分、硫分、水分或热值接近订单边界时，应作为风险参考方案处理，并建议执行前重新采样化验或提高优质煤比例。',1,57,'边界订单,商品煤,复核,风险提示','rag_knowledge',50,'9','bge-m3',1,'2026-05-30 20:28:19','2026-05-30 20:28:19'),
	(10,10,'RAG-EXP26-010-C001','反例案例表明，在硫分上限0.50%的订单中过高比例使用吕梁高硫煤会导致硫分超限。系统应将高硫煤识别为风险物料，并建议替换为低硫煤。',1,65,'高硫煤,反例,硫分超限,不可行','rag_knowledge',51,'10','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(11,11,'RAG-BLEND-001-C001','配煤方案生成时，灰分、硫分、水分、挥发分和发热量等指标可先按各煤种配比进行线性加权估算：混煤指标 = Σ(单煤指标 × 配比)。该方法适合作为方案初筛和硬约束校验的工程近似，但执行前仍需结合最终化验结果校正。适用场景：智能配煤初筛、候选方案质量预测、人工经验方案复核。来源依据：煤质及煤分析术语标准中对煤质分析指标的规范化定义，以及电厂配煤掺烧实践中对煤质指标的加权评价方法。',1,188,'配煤方案,线性加权,灰分,硫分,水分,发热量,质量预测','rag_knowledge',52,'11','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(12,12,'RAG-BLEND-002-C001','灰分是煤中不可燃矿物质燃烧后的残留物相关指标。配煤时灰分越高，通常会增加灰渣量、输灰压力和受热面积灰风险。对灰分上限严格的订单，应避免高灰煤作为主配煤；当必须使用高灰低价煤时，应限制其配比，并用低灰煤进行质量补偿。适用场景：低灰订单、商品煤质量达标、电厂锅炉灰渣控制。',1,134,'灰分控制,低灰煤,高灰煤限配,质量约束,锅炉积灰','rag_knowledge',53,'12','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(13,13,'RAG-BLEND-003-C001','硫分是配煤质量和环保约束中的关键指标。订单硫分上限较低时，应优先选择低硫煤作为主配煤，高硫煤原则上不参与或仅低比例参与；当硫分接近上限时，应在方案中保留安全余量，避免煤质波动、采样误差或批次差异造成最终产品超标。适用场景：环保限硫订单、低硫动力煤、低硫商品煤。',1,130,'硫分控制,低硫订单,高硫煤限配,环保约束,安全余量','rag_knowledge',54,'13','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(14,14,'RAG-BLEND-004-C001','水分会影响煤的有效热值、运输和储存稳定性。高水分煤参与配煤时，容易拉低单位质量发热量，并增加运输、堆存和燃烧过程中的不确定性。水分上限严格的订单，应限制高水分煤配比，优先使用近期化验水分稳定的煤种，执行前建议复检。适用场景：低水分订单、夏季运输、长距离运输、低热值风险控制。',1,137,'水分控制,高水分煤限配,热值补偿,运输储存,复检','rag_knowledge',55,'14','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(15,15,'RAG-BLEND-005-C001','发热量是评价动力煤能量价值的重要指标。订单设置发热量下限时，配煤方案预测热值必须不低于订单要求；若基础低价煤热值不足，应引入高热值煤进行补偿，同时评估成本上升和库存可用性。热值余量过小时，应提示执行风险。适用场景：高热值订单、动力煤保供、低价煤掺配。',1,125,'发热量,热值补偿,高热值煤,动力煤,质量约束','rag_knowledge',56,'15','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(16,16,'RAG-BLEND-006-C001','挥发分影响煤的着火、燃烧稳定性和适用场景。动力煤和气化用煤配煤时，挥发分可作为参考指标：挥发分过低可能影响着火和燃烧稳定性，挥发分过高则可能带来燃烧组织和安全管理压力。若订单给出挥发分参考值，系统应计算预测挥发分偏差并提示风险。适用场景：气化用煤、动力煤燃烧稳定性、挥发分参考订单。',1,141,'挥发分,气化用煤,燃烧稳定性,质量偏差,参考指标','rag_knowledge',57,'16','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(17,17,'RAG-BLEND-007-C001','低价煤可降低吨煤成本，但往往伴随灰分、水分、硫分或热值方面的质量压力。成本优先订单可适度提高低成本煤比例，但必须先满足灰分、硫分、水分上限和发热量下限；当低价煤导致任一指标安全余量过低时，应降低其配比或增加质量补偿煤。适用场景：成本优先、库存消纳、经济煤订单。',1,130,'成本控制,低价煤,质量边界,成本优先,库存消纳','rag_knowledge',58,'17','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(18,18,'RAG-BLEND-008-C001','配煤方案不仅要满足煤质约束，还应满足可执行性约束。参与煤种计划用量不得超过可用库存；执行后库存余量过低时，应提示调拨、分仓合计、补库或降低该煤种配比。大批量订单应重点核查多仓可用量、锁定量和交付节奏。适用场景：库存不足预警、大批量订单、方案执行风险。',1,125,'库存安全,可用库存,调拨,大批量订单,执行风险','rag_knowledge',59,'18','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(19,19,'RAG-BLEND-009-C001','煤质会受矿区、批次、洗选工艺、堆存时间和采样误差影响。对硫分、水分、热值等接近订单边界的方案，应标记为风险参考并建议执行前复检；当历史批次波动较大时，应提高安全余量或选择煤质更稳定的批次。适用场景：边界订单、风险方案、最终产品质检。',1,116,'煤质波动,复检,边界订单,质量安全余量,批次差异','rag_knowledge',60,'19','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(20,20,'RAG-BLEND-010-C001','火电厂配煤掺烧可采用预混掺烧、分磨掺烧、分仓分时掺烧等方式。预混掺烧有利于入炉煤质稳定，但对煤场混匀和堆取料管理要求较高；分磨掺烧便于控制不同煤种比例，但需要关注磨煤机适应性和燃烧组织；分时掺烧适合临时保供或试烧，但煤质波动可能更大。配煤系统生成方案时，应说明方案适合的执行方式。',1,140,'配煤掺烧,预混掺烧,分磨掺烧,分时掺烧,火电厂','rag_knowledge',61,'20','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(21,21,'RAG-BLEND-011-C001','高水分、低热值煤用于降低成本或消纳库存时，应设置配比上限。该类煤会降低混煤热值，并可能增加燃烧、运输和堆存风险。若订单热值下限较高或水分上限严格，应减少高水分低热值煤比例，必要时引入高热值低水分煤进行补偿。适用场景：准东高水分煤、褐煤、低热值煤掺配。',1,125,'高水分煤,低热值煤,褐煤,限配,热值补偿','rag_knowledge',62,'21','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(22,22,'RAG-BLEND-012-C001','劣质煤价格较低，可能降低采购成本，但其灰分、硫分、水分和热值劣势会增加煤耗、脱硫压力、输灰压力或设备运行风险。系统评价劣质煤方案时，不能只看单价，应同时计算吨煤成本、质量偏差、执行风险和环保约束。适用场景：劣质煤掺烧、低成本订单、风险参考方案。',1,122,'劣质煤,经济性,吨煤成本,环保约束,执行风险','rag_knowledge',63,'22','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(23,23,'RAG-BLEND-013-C001','高硫煤参与配煤时，应根据订单硫分上限和脱硫能力设置配比边界。低硫订单中高硫煤原则上不参与；常规硫分订单中可低比例参与，但必须通过低硫煤补偿，并保留硫分安全余量。适用场景：中高硫煤、低硫订单、环保约束订单。',1,102,'高硫煤,硫分安全余量,低硫煤补偿,环保约束','rag_knowledge',64,'23','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(24,24,'RAG-BLEND-014-C001','配煤方案中高灰煤比例偏高时，应提示锅炉积灰、结渣和飞灰量增加风险。对发电用煤或锅炉燃烧场景，灰分控制不仅影响质量验收，也影响运行经济性和设备维护。高灰煤可用于成本控制，但不宜在灰分约束严格的订单中作为主配煤。',1,104,'灰分,结渣,积灰,锅炉运行,飞灰','rag_knowledge',65,'24','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(25,25,'RAG-BLEND-015-C001','煤炭洗选加工能够改善和稳定煤质，是煤炭清洁高效利用的重要前提。配煤系统在选择候选物料时，应优先使用质量数据完整、批次来源清晰、洗选后指标稳定的产品批次；对原煤或来源不明批次，应提高风险等级或要求补充化验数据。',1,104,'洗选加工,煤质稳定,产品批次,批次来源,清洁高效利用','rag_knowledge',66,'25','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(26,26,'RAG-BLEND-016-C001','煤炭清洁高效利用强调分质分级利用。配煤方案应根据不同订单的灰分、硫分、水分、热值和用途要求匹配不同煤种，避免高品质煤被低价值订单过度消耗，也避免低品质煤进入严格质量订单造成超标风险。适用场景：订单分级、库存优化、资源综合利用。',1,113,'分质分级,清洁高效利用,订单分级,资源优化,库存优化','rag_knowledge',67,'26','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(27,27,'RAG-BLEND-017-C001','动力煤订单通常重点关注发热量、硫分、灰分和水分。若订单为高热值低硫场景，排序时应优先保证发热量和硫分约束；若订单为成本敏感场景，可在满足质量底线后优先选择低成本、高库存煤种。适用场景：动力煤订单、保供订单、成本优先订单。',1,110,'动力煤,高热值,低硫,成本优先,质量排序','rag_knowledge',68,'27','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(28,28,'RAG-BLEND-018-C001','气化用煤配煤应关注挥发分、热值、灰分和硫分。挥发分偏离目标过大时，可能影响气化反应稳定性；热值不足时应引入高热值煤补偿；灰分和硫分偏高则会增加后续处理压力。适用场景：煤化工气化用煤、挥发分参考订单。',1,99,'气化用煤,挥发分,热值,煤化工,质量约束','rag_knowledge',69,'28','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(29,29,'RAG-BLEND-019-C001','大批量订单执行时，单一煤种或单一仓库可能无法完全覆盖计划用量。系统生成方案后，应核查各参与煤种的可用库存、锁定库存和多仓合计能力；若单仓不足但总库存可满足，应提示分仓调拨或分批发运。适用场景：5000吨以上订单、保供订单、多仓库存。',1,116,'大批量订单,分仓执行,分批发运,库存调拨,保供','rag_knowledge',70,'29','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(30,30,'RAG-BLEND-020-C001','可执行方案不应只满足等号边界。硫分、灰分、水分等上限指标应保留一定安全余量，发热量下限指标也应保留热值余量。若任一关键指标余量过小，应在方案解释中标记风险，并建议复检或调整配比。适用场景：边界达标方案、风险参考方案、执行前审查。',1,114,'安全余量,边界达标,风险参考,复检,配比调整','rag_knowledge',71,'30','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(31,31,'RAG-BLEND-021-C001','订单场景：5000吨低硫动力煤，硫分上限0.80%，热值下限5200 kcal/kg。参考方案：低硫长焰煤50% + 低灰动力煤30% + 高热值补偿煤20%。执行要点：低硫煤作为主配，低灰煤控制灰分，高热值煤补偿热值。风险控制：若硫分预测接近0.80%，应减少中硫煤比例或增加低硫煤比例。',1,145,'低硫动力煤,三煤种组合,高热值补偿,案例','rag_knowledge',72,'31','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(32,32,'RAG-BLEND-022-C001','订单场景：库存消纳型动力煤订单，质量要求相对宽松，关注吨煤成本。参考方案：高库存低价煤40% + 常规动力煤35% + 质量补偿煤25%。执行要点：先校验灰分、硫分、水分和热值硬约束，再提高高库存煤比例。风险控制：高库存煤若为高水分或高灰煤，应设置配比上限。',1,129,'库存消纳,成本控制,低价煤,质量补偿,案例','rag_knowledge',73,'32','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(33,33,'RAG-BLEND-023-C001','订单场景：热值下限较高的动力煤订单。风险方案：低热值低价煤比例超过50%，导致预测发热量低于订单下限。处理建议：降低低热值煤比例，引入高热值煤补偿，并重新计算吨煤成本和热值安全余量。该案例适用于解释“成本较低但质量不可执行”的风险参考方案。',1,120,'低热值煤,热值不足,风险案例,成本质量冲突','rag_knowledge',74,'33','bge-m3',1,'2026-05-30 20:28:20','2026-05-30 20:28:20'),
	(34,34,'RAG-BLEND-024-C001','订单场景：水分上限严格且运输周期较长。风险方案：高水分煤比例偏高，预测水分接近或超过订单上限。处理建议：降低高水分煤比例，选用低水分煤补偿，执行前复检并关注堆存时间。该案例适用于水分敏感订单的风险提示。',1,101,'高水分煤,水分边界,复检,风险案例,运输堆存','rag_knowledge',75,'34','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(35,35,'RK-EXP26-001-C001','规则编号：RK-EXP26-001\n规则名称：低硫订单高硫煤限配规则\n规则类型：配比约束\n适用范围：低硫订单、硫分边界订单\n业务阶段：blending\n质量指标：sulfur\n物料类型：动力煤\n规则内容：当订单硫分上限小于等于0.60%时，高硫煤或硫分大于1.20%的煤种不宜参与配煤；如必须使用，应严格控制比例并触发风险提示。\n来源说明：EXP26实验规则',1,179,'配比约束,低硫订单、硫分边界订单,blending,sulfur,动力煤','rule_knowledge',21,'35','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(36,36,'RK-EXP26-002-C001','规则编号：RK-EXP26-002\n规则名称：高热值订单热值补偿规则\n规则类型：质量约束\n适用范围：高热值订单\n业务阶段：blending\n质量指标：calorific\n物料类型：动力煤\n规则内容：当订单发热量下限大于等于6000 kcal/kg时，应优先引入高热值低灰煤，并控制低热值煤掺配比例，防止热值安全余量不足。\n来源说明：EXP26实验规则',1,175,'质量约束,高热值订单,blending,calorific,动力煤','rule_knowledge',22,'36','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(37,37,'RK-EXP26-003-C001','规则编号：RK-EXP26-003\n规则名称：库存消纳订单风险规则\n规则类型：库存约束\n适用范围：库存消纳订单\n业务阶段：blending\n质量指标：calorific,moisture\n物料类型：动力煤\n规则内容：库存消纳型订单可以适当提高积压低价煤比例，但必须同时满足热值下限和水分上限；若热值余量低于100 kcal/kg，应标记为风险参考。\n来源说明：EXP26实验规则',1,189,'库存约束,库存消纳订单,blending,calorific,moisture,动力煤','rule_knowledge',23,'37','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(38,38,'RK-EXP26-004-C001','规则编号：RK-EXP26-004\n规则名称：水分严格订单低水分优先规则\n规则类型：质量约束\n适用范围：水分严格订单\n业务阶段：blending\n质量指标：moisture\n物料类型：动力煤\n规则内容：当订单水分上限小于等于8.0%时，应优先选择低水分煤种，并限制准东高水分煤和煤泥参与。\n来源说明：EXP26实验规则',1,159,'质量约束,水分严格订单,blending,moisture,动力煤','rule_knowledge',24,'38','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(39,39,'RK-EXP26-005-C001','规则编号：RK-EXP26-005\n规则名称：单煤依赖风险规则\n规则类型：经验规则\n适用范围：所有配煤订单\n业务阶段：blending\n质量指标：ratio\n物料类型：all\n规则内容：单一煤种配比超过75%时，方案对该煤源波动敏感，应触发单煤依赖风险并建议引入第二或第三种煤种。\n来源说明：EXP26实验规则',1,155,'经验规则,所有配煤订单,blending,ratio,all','rule_knowledge',25,'39','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(40,40,'RK-EXP26-006-C001','规则编号：RK-EXP26-006\n规则名称：低价高灰煤使用边界规则\n规则类型：经验规则\n适用范围：成本优先订单\n业务阶段：blending\n质量指标：ash,calorific\n物料类型：middlings/slime\n规则内容：平鲁高灰低价煤和煤泥可以降低成本，但在灰分严格或热值较高订单中应控制比例，避免灰分超限或热值不足。\n来源说明：EXP26实验规则',1,180,'经验规则,成本优先订单,blending,ash,calorific,middlings/slime','rule_knowledge',26,'40','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(41,41,'RK-EXP26-007-C001','规则编号：RK-EXP26-007\n规则名称：优质煤库存保护规则\n规则类型：库存约束\n适用范围：优质煤库存管理\n业务阶段：blending\n质量指标：inventory\n物料类型：动力煤\n规则内容：神木、府谷、沁水等优质低硫高热煤库存有限时，应优先用于高优先级或严格质量订单，普通订单不宜过度消耗。\n来源说明：EXP26实验规则',1,164,'库存约束,优质煤库存管理,blending,inventory,动力煤','rule_knowledge',27,'41','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(42,42,'RK-EXP26-008-C001','规则编号：RK-EXP26-008\n规则名称：边界商品煤复核规则\n规则类型：经验规则\n适用范围：边界订单\n业务阶段：blending\n质量指标：ash,sulfur,moisture,calorific\n物料类型：all\n规则内容：当预测灰分、硫分、水分或热值接近订单边界时，应标记风险参考并建议执行前复核最新化验结果。\n来源说明：EXP26实验规则',1,175,'经验规则,边界订单,blending,ash,sulfur,moisture,calorific,all','rule_knowledge',28,'42','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(43,43,'CS-EXP26-001-C001','案例编号：CS-EXP26-001\n案例名称：低硫高热电煤成功案例\n订单描述：5000吨低硫高热订单，硫分≤0.60%，热值≥5600 kcal/kg。\n配煤方案：采用神木低灰煤、府谷低硫煤与鄂尔多斯均衡煤组合，控制高硫煤参与比例。\n执行结果：质量达标，热值余量充足，成本略高但符合优先级要求。\n质量结果：灰分、硫分和热值均满足要求\n成本结果：2520000.00\n效果评价：质量优先订单可参考\n业务阶段：blending\n相关批次：PB-EXP26-SM-001',1,232,'blending,灰分、硫分和热值均满足要求,质量优先订单可参考,PB-EXP26-SM-001','case_sample',18,'43','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(44,44,'CS-EXP26-002-C001','案例编号：CS-EXP26-002\n案例名称：成本保供成功案例\n订单描述：9000吨成本敏感订单，灰分和硫分约束相对宽松。\n配煤方案：采用五彩湾低成本煤、晋北中硫煤与少量鄂尔多斯均衡煤组合。\n执行结果：在满足硬约束前提下降低吨煤成本。\n质量结果：质量达标，成本较低\n成本结果：3303000.00\n效果评价：成本优先订单可参考\n业务阶段：blending\n相关批次：PB-EXP26-WCW-001',1,199,'blending,质量达标，成本较低,成本优先订单可参考,PB-EXP26-WCW-001','case_sample',19,'44','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(45,45,'CS-EXP26-003-C001','案例编号：CS-EXP26-003\n案例名称：库存消纳风险案例\n订单描述：7000吨库存消纳订单，要求热值≥5000 kcal/kg。\n配煤方案：五彩湾低成本煤为主，搭配晋北或榆林煤进行热值补偿。\n执行结果：方案达标但热值余量较小，执行前需复核煤质。\n质量结果：热值边界，风险参考\n成本结果：2786000.00\n效果评价：库存消纳订单需关注热值余量\n业务阶段：blending\n相关批次：PB-EXP26-WCW-001',1,211,'blending,热值边界，风险参考,库存消纳订单需关注热值余量,PB-EXP26-WCW-001','case_sample',20,'45','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(46,46,'CS-EXP26-004-C001','案例编号：CS-EXP26-004\n案例名称：边界商品煤复核案例\n订单描述：3200吨严格商品煤订单，灰分≤10%，硫分≤0.55%，热值≥6000。\n配煤方案：使用神木、府谷、沁水优质煤组合，避免低价高灰煤参与。\n执行结果：质量满足但优质煤库存消耗较快。\n质量结果：边界质量达标，库存需关注\n成本结果：1760000.00\n效果评价：严格订单需优先保证质量\n业务阶段：blending\n相关批次：PB-EXP26-QS-001',1,214,'blending,边界质量达标，库存需关注,严格订单需优先保证质量,PB-EXP26-QS-001','case_sample',21,'46','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(47,47,'CS-EXP26-005-C001','案例编号：CS-EXP26-005\n案例名称：水分严格控制案例\n订单描述：4500吨水分≤7.5%的订单。\n配煤方案：引入哈密低水分煤与神木低灰煤，限制高水分准东煤和煤泥。\n执行结果：水分达标，成本中等。\n质量结果：水分控制有效\n成本结果：2150000.00\n效果评价：水分严格订单可参考\n业务阶段：blending\n相关批次：PB-EXP26-HM-001',1,180,'blending,水分控制有效,水分严格订单可参考,PB-EXP26-HM-001','case_sample',22,'47','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21'),
	(48,48,'CS-EXP26-006-C001','案例编号：CS-EXP26-006\n案例名称：高硫煤限配失败案例\n订单描述：低硫订单中错误加入过高比例高硫煤。\n配煤方案：吕梁高硫煤比例过高导致硫分超限。\n执行结果：方案不可执行，应降低高硫煤比例或替换为低硫煤。\n质量结果：硫分超限\n成本结果：1900000.00\n效果评价：作为反例用于RAG解释\n业务阶段：blending\n相关批次：PB-EXP26-LL-001',1,184,'blending,硫分超限,作为反例用于RAG解释,PB-EXP26-LL-001','case_sample',23,'48','bge-m3',1,'2026-05-30 20:28:21','2026-05-30 20:28:21');
