INSERT INTO `rule_knowledge` (`id`, `rule_code`, `rule_name`, `rule_type`, `rule_content`, `applicable_scope`, `priority_level`, `status`, `source_desc`, `create_time`, `update_time`, `business_stage`, `quality_indicator`, `material_type`)
VALUES
	(1,'R001','低硫订单优先低硫煤规则','经验规则','当订单硫分上限较低时，应优先选择硫分较低且煤质稳定的产品批次参与配煤，并谨慎使用硫分接近上限的批次。','低硫订单、环保约束严格订单',5,0,'根据商品煤质量管理要求和智能配煤实践整理','2026-04-25 16:14:38','2026-05-29 09:10:01','blending','sulfur','product_batch'),
	(2,'R002','高硫煤限配规则','配比约束','当订单硫分上限小于等于0.80%时，硫分偏高或波动较大的煤种不宜作为主配煤种，应限制其参与比例。','target_sulfur <= 0.80 的订单',5,0,'根据硫分约束整理','2026-04-25 16:14:38','2026-05-29 09:10:01','blending','sulfur','product_batch'),
	(3,'R003','灰分约束优先校验规则','质量约束','配煤方案生成后必须校验预测灰分，若预测灰分高于订单灰分上限，则该方案应判定为不可行。','全部订单',5,0,'根据煤质指标约束整理','2026-04-25 16:14:38','2026-05-29 09:10:01','blending','ash','product_batch'),
	(4,'R004','发热量下限校验规则','质量约束','配煤方案预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种补偿。','含目标发热量下限的订单',5,0,'根据动力煤质量评价和配煤优化要求整理','2026-04-25 16:14:38','2026-05-29 09:10:01','blending','calorific','product_batch'),
	(5,'R005','库存可用性约束规则','库存约束','参与配煤的产品批次必须存在可用库存，且方案使用量不得超过可用量；已执行方案应同步锁定或扣减库存。','全部订单',5,0,'根据配煤方案可执行性要求整理','2026-04-25 16:14:38','2026-05-29 09:10:01','inventory','quantity','product_batch'),
	(6,'R006','分质堆存与分质装车规则','经验规则','不同质量商品煤应分质堆存、分质装车，并建立商品煤质量档案，避免储运环节降低煤炭质量。','产品仓储和发运',4,0,'根据商品煤质量管理要求整理','2026-04-25 16:14:38','2026-05-29 09:10:01','shipment','quality','final_product'),
	(7,'R007','低成本煤使用边界规则','配比约束','低价煤种可用于降低方案成本，但若灰分、水分或硫分偏高，应设置使用边界，避免质量不达标。','成本优先订单',4,0,'根据成本与质量多目标权衡整理','2026-04-25 16:14:38','2026-05-29 09:10:01','blending','ash,moisture,sulfur','product_batch'),
	(8,'R008','相似案例参考规则','经验规则','当存在与当前订单在灰分、硫分、发热量或需求量方面相近的历史案例时，可将其作为候选方案和解释生成的参考。','案例检索和RAG解释',3,0,'根据案例库设计要求整理','2026-04-25 16:14:38','2026-05-29 09:10:01','rag','case','all'),
	(9,'RK-TUNE-001','低硫订单优先低硫煤规则','质量约束','当订单硫分上限小于等于0.60%时，应优先选择硫分低于0.45%的煤种；硫分高于0.80%的煤种原则上不参与或低比例参与。','低硫电煤、环保限硫订单',5,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','sulfur_content','coal_type'),
	(10,'RK-TUNE-002','高灰煤限配规则','配比约束','当煤种灰分高于20%时，若订单灰分上限小于18%，该煤种配比建议不超过20%；若订单灰分上限小于14%，原则上不推荐使用。','高灰动力煤参与配煤',5,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','ash_content','coal_type'),
	(11,'RK-TUNE-003','高水分煤限配规则','配比约束','当煤种水分高于15%时，若订单水分上限小于12%，该煤种配比建议不超过15%；若订单水分上限小于10%，原则上不推荐使用。','褐煤、高水分煤',4,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','moisture_content','coal_type'),
	(12,'RK-TUNE-004','高热值补偿规则','经验规则','当订单发热量下限高于5800 kcal/kg时，应引入高热值煤进行补偿，但应同时控制成本和库存余量。','高热值订单',4,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','calorific_value','coal_type'),
	(13,'RK-TUNE-005','成本优先订单规则','经验规则','当订单优先级为1且质量约束较宽松时，可优先使用低成本煤种，但必须保证灰分、硫分、水分和热值全部满足硬约束。','成本优先订单',3,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','cost,quality','coal_type'),
	(14,'RK-TUNE-006','库存安全余量规则','库存约束','生成方案后，任一参与煤种执行后可用库存低于800吨时，应提示库存风险；低于300吨时不建议作为推荐方案。','库存稳定性评估',4,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','available_quantity','coal_type'),
	(15,'RK-TUNE-007','中硫煤限配规则','配比约束','当煤种硫分在0.80%至1.00%之间时，若订单硫分上限小于0.90%，该煤种配比建议不超过25%。','中硫动力煤',4,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','sulfur_content','coal_type'),
	(16,'RK-TUNE-008','气化用煤挥发分参考规则','质量约束','气化用煤应关注挥发分与热值，挥发分过低的无烟煤、贫瘦煤不宜大比例参与气化用煤方案。','煤化工气化用煤',4,0,'模型调优测试规则','2026-04-25 22:05:30','2026-05-29 09:10:01','blending','volatile_content,calorific_value','coal_type'),
	(17,'RK-EXP-001','严格低硫订单质量余量规则','质量约束','当订单硫分上限小于等于0.60%时，推荐方案预测硫分不宜贴近上限，建议保留不少于0.05个百分点的安全余量；若硫分预测值高于上限的90%，应给出风险提示。','严格低硫电煤、环保限硫订单',5,0,'论文实验补充规则，来源于严格低硫订单风险反馈案例抽象','2026-05-08 09:12:26','2026-05-29 09:10:01','blending','sulfur_content','product_batch'),
	(18,'RK-EXP-002','高水分低成本煤使用边界规则','配比约束','低成本高水分煤可用于降低成本，但当订单水分上限小于等于10%时，高水分煤不宜作为主配批次；当订单水分上限小于等于8%时，应原则上避免使用水分高于15%的批次。','成本优先订单、严格商品煤订单',4,0,'论文实验补充规则，来源于高水分煤超配风险案例抽象','2026-05-08 09:12:26','2026-05-29 09:10:01','blending','moisture_content,cost','product_batch'),
	(19,'RK-EXP-003','气化用煤挥发分与热值协同规则','质量约束','气化用煤方案应同时关注挥发分、发热量和硫分。若订单给出挥发分参考值，应优先选择挥发分接近参考值且热值达标的批次，并避免低挥发分煤大比例参与。','煤化工气化用煤订单',4,0,'论文实验补充规则，来源于气化用煤业务指标抽象','2026-05-08 09:12:26','2026-05-29 09:10:01','blending','volatile_content,calorific_value,sulfur_content','product_batch'),
	(20,'RK-EXP-004','高热值应急订单成本权衡规则','经验规则','当订单发热量下限大于等于6200 kcal/kg且优先级较高时，应优先保障热值约束，可引入高热值高价批次，但需在解释中说明成本上升原因和替代方案。','高热值应急补仓订单',4,0,'论文实验补充规则，来源于高热值应急订单案例抽象','2026-05-08 09:12:26','2026-05-29 09:10:01','blending','calorific_value,cost','product_batch'),
	(21,'RK-EXP26-001','低硫订单高硫煤限配规则','配比约束','当订单硫分上限小于等于0.60%时，高硫煤或硫分大于1.20%的煤种不宜参与配煤；如必须使用，应严格控制比例并触发风险提示。','低硫订单、硫分边界订单',5,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','sulfur','动力煤'),
	(22,'RK-EXP26-002','高热值订单热值补偿规则','质量约束','当订单发热量下限大于等于6000 kcal/kg时，应优先引入高热值低灰煤，并控制低热值煤掺配比例，防止热值安全余量不足。','高热值订单',5,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','calorific','动力煤'),
	(23,'RK-EXP26-003','库存消纳订单风险规则','库存约束','库存消纳型订单可以适当提高积压低价煤比例，但必须同时满足热值下限和水分上限；若热值余量低于100 kcal/kg，应标记为风险参考。','库存消纳订单',4,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','calorific,moisture','动力煤'),
	(24,'RK-EXP26-004','水分严格订单低水分优先规则','质量约束','当订单水分上限小于等于8.0%时，应优先选择低水分煤种，并限制准东高水分煤和煤泥参与。','水分严格订单',4,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','moisture','动力煤'),
	(25,'RK-EXP26-005','单煤依赖风险规则','经验规则','单一煤种配比超过75%时，方案对该煤源波动敏感，应触发单煤依赖风险并建议引入第二或第三种煤种。','所有配煤订单',3,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','ratio','all'),
	(26,'RK-EXP26-006','低价高灰煤使用边界规则','经验规则','平鲁高灰低价煤和煤泥可以降低成本，但在灰分严格或热值较高订单中应控制比例，避免灰分超限或热值不足。','成本优先订单',3,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','ash,calorific','middlings/slime'),
	(27,'RK-EXP26-007','优质煤库存保护规则','库存约束','神木、府谷、沁水等优质低硫高热煤库存有限时，应优先用于高优先级或严格质量订单，普通订单不宜过度消耗。','优质煤库存管理',4,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','inventory','动力煤'),
	(28,'RK-EXP26-008','边界商品煤复核规则','经验规则','当预测灰分、硫分、水分或热值接近订单边界时，应标记风险参考并建议执行前复核最新化验结果。','边界订单',5,1,'EXP26实验规则','2026-05-29 09:10:01','2026-05-29 09:10:01','blending','ash,sulfur,moisture,calorific','all');
